import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    return (major, minor, patch), pre

def _pre_ids(pre):
    return pre.split('.')

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _cmp_pre(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    aids = _pre_ids(a)
    bids = _pre_ids(b)
    for x, y in zip(aids, bids):
        c = _cmp_id(x, y)
        if c != 0:
            return c
    return (len(aids) > len(bids)) - (len(aids) < len(bids))

def _compare(v1, v2):
    (core1, pre1) = _parse(v1)
    (core2, pre2) = _parse(v2)
    if core1 != core2:
        return (core1 > core2) - (core1 < core2)
    return _cmp_pre(pre1, pre2)

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_compare))

